      SUBROUTINE TWIT1CCC     DETERMINES CONTRIBUTION OF FIRST-ORDER TRANSFER MATRIX TOC     TRANSFORM OF PARTIALS OF BEAM CENTROIDCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'COCOM.CIN'      INCLUDE 'ELM7D.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'R.CIN'C      DO 110 J = 1, 6      SS = 0.0      DO 105 K = 1, 6      SS = SS + R(J,K)*COV(K,NV2)  105 CONTINUE      COT(J) = SS  110 CONTINUEC      RETURN      END